  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Aprepitant, a close structural analogue sharing the 3,5-bis(trifluoromethyl)phenyl and chiral methyl carbinol ether motif, has a mean absolute oral bioavailability of 67% in healthy volunteers under fasting conditions, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Maraviroc, the highest-transfer analogue, has an observed absolute oral bioavailability of 23.1% (95% CI 19.2-27.8) in humans, above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Silodosin has an absolute oral bioavailability of 32.2% in healthy adult men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Odanacatib has an absolute oral bioavailability of 30% at a 50 mg fasted oral dose in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dutasteride has an absolute oral bioavailability of approximately 60% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental analogues report absolute oral bioavailability values above 20% or explicitly describe high oral bioavailability, with no affirmative evidence of low F. The closest structural analogue, aprepitant, shows 59-67% absolute bioavailability, and the highest-transfer analogue, maraviroc, shows 23-33%, both supporting a high F >= 20% prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "Some analogues show dose- or food-dependent bioavailability, so the exact F for the query may vary, but all reported values remain above the 20% threshold.",
    "The query's spiro lactam/amine motif may alter solubility or efflux relative to the closest analogues, but no affirmative low-bioavailability evidence was provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

